export const InfoModal = ({
  onClose,
  onSelect,
  onCustomInputClear,
  options,
  text,
  Context,
  DelConfirm,
  CompareCards,
  MoreActions,
  FlowComposer,
  initialCustomInput = '',
  comparisonScrollRef,
  // Лише меню рядка навігації передає мову; решта модалок лишаються як були.
  language,
}) => {
  const closeMenuLabel = language ? uiText('Закрити меню', language) : 'Закрити меню';
  const openedAtRef = useRef(Date.now());
  const comparisonContentRef = useRef(null);
  useEffect(() => {
    if (text !== 'compareCards') return undefined;
    const body = document.body;
    const previousStyle = body.getAttribute('style');
    const scrollY = window.scrollY;
    Object.assign(body.style, { position: 'fixed', top: `-${scrollY}px`, width: '100%', overflow: 'hidden' });
    if (comparisonContentRef.current) comparisonContentRef.current.scrollTop = comparisonScrollRef?.current || 0;
    return () => {
      if (previousStyle === null) body.removeAttribute('style');
      else body.setAttribute('style', previousStyle);
      window.scrollTo(0, scrollY);
    };
  }, [text, comparisonScrollRef]);

  const delProfile = (
    <>
      <ModalTitle>Видалення анкети</ModalTitle>
      <ModalText>Щоб видалити анкету, відправте запит на пошту</ModalText>
      <a href="mailto:KnowMeEggDonor@gmail.com?subject=Видаліть мою анкету" style={{ color: 'inherit', textDecoration: 'none' }}>
        <OrangeStrong>KnowMeEggDonor@gmail.com</OrangeStrong>
      </a>
      <ModalText style={{ marginTop: 4 }}>з темою листа «Видаліть мою анкету».</ModalText>
    </>
  );

  const delConfirm = (
    <>{DelConfirm && <DelConfirm/>}
  </>
);

  const compareCards = (
    <>{CompareCards && <CompareCards/>}
  </>
);

  const moreActions = (
    <>{MoreActions && <MoreActions />}</>
  );
  
  const dotsMenu = (
    <>{Context && <Context/>}
    </>
  );

  const flowComposer = (
    <>{FlowComposer && <FlowComposer />}</>
  );

  //////////////////////////////
  const [customInput, setCustomInput] = useState(''); // Стан для власного вводу

  useEffect(() => {
    if (text !== 'pickerOptions') {
      return;
    }
    const preparedValue = typeof initialCustomInput === 'string' ? initialCustomInput.trim() : '';
    setCustomInput(preparedValue);
  }, [initialCustomInput, text]);

  const handleSelect = option => {
    onSelect(option); // Вибрати звичайну опцію
  };

  const handleCustomInputChange = e => {
    const nextValue = e.target.value;
    if (customInput.trim() && !nextValue.trim()) {
      onCustomInputClear?.();
    }
    setCustomInput(nextValue); // Оновлення стану з власним ввідом
  };

  const handleConfirm = () => {
    if (!customInput.trim()) return;
    onSelect({ placeholder: customInput }); // Передати введене значення
    setCustomInput(''); // Очистити поле
  };

  const handleCustomInputDelete = () => {
    setCustomInput('');
    onCustomInputClear?.();
  };

  const handleKeyDown = e => {
    if (e.key === 'Enter') {
      handleConfirm();
    }
  };

  const pickerOptions = (
    <>
    {options && <><OptionsList>
        {options.map(option => (
          <OptionItem key={option.placeholder} onClick={() => handleSelect(option)}>
            {option.placeholder} / {option.ukrainian}
          </OptionItem>
        ))}
      </OptionsList>
      <>
        <CustomInputWrapper>
          <CustomInput
            type="text"
            value={customInput}
            onChange={handleCustomInputChange}
            placeholder="Інший варіант"
            onKeyDown={handleKeyDown}
          />
          {!!customInput && (
            <InlineDeleteButton onClick={handleCustomInputDelete} aria-label="delete custom value">
              &times;
            </InlineDeleteButton>
          )}
        </CustomInputWrapper>
        <ActionRow>
          <OkButton onClick={handleConfirm} disabled={!customInput.trim()}>
            ОК
          </OkButton>
        </ActionRow>
      </> </>}
    </>
  );

  let ContentComponent = ModalContent;
  let body = null;

  switch (text) {
    case 'delProfile':
      body = delProfile;
      break;
    case 'pickerOptions':
      body = pickerOptions;
      break;
    case 'dotsMenu':
      body = dotsMenu;
      break;
    case 'delConfirm':
      body = delConfirm;
      break;
    case 'compareCards':
      body = compareCards;
      break;
    case 'moreActions':
      body = moreActions;
      break;
    case 'flowComposer':
      body = flowComposer;
      break;
    default:
      body = null;
  }

  if (text === 'moreActions' || text === 'flowComposer') {
    ContentComponent = LargeModalContent;
  }

  if (text === 'dotsMenu') {
    ContentComponent = MenuModalContent;
  }
  if (text === 'compareCards') ContentComponent = ComparisonModalContent;

  // Escape закриває будь-яке вікно цієї модалки — меню профілю, підтвердження,
  // список варіантів. Доти на десктопі його закривали лише хрестик і дотик
  // повз вікно. Коли всередині відкрите вкладене вікно (підтвердження
  // виходу в меню профілю), Escape закриває лише його.
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  useEffect(() => {
    const onKeyDown = event => {
      if (event.key !== 'Escape' || event.defaultPrevented) return;
      // Слухач вкладеного вікна ставиться пізніше за цей і спрацьовує після
      // нього, тож саму позначку тут ще не видно — питаємо розмітку.
      if (comparisonContentRef.current?.querySelector('[aria-modal="true"]')) return;
      onCloseRef.current?.(event);
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, []);

  const handleOverlayClick = event => {
    if (Date.now() - openedAtRef.current < 250) {
      return;
    }
    if (text === 'pickerOptions' && customInput.trim()) {
      onSelect({ placeholder: customInput.trim() });
      return;
    }
    onClose(event);
  };

  return (
    <ModalOverlay $sheet={text === 'dotsMenu'} onClick={handleOverlayClick}>
      <ContentComponent
        role={text === 'compareCards' ? 'dialog' : undefined}
        aria-modal={text === 'compareCards' ? true : undefined}
        aria-label={text === 'compareCards' ? 'Порівняти картки' : undefined}
        ref={comparisonContentRef}
        onScroll={event => {
          if (text === 'compareCards' && comparisonScrollRef) comparisonScrollRef.current = event.currentTarget.scrollTop;
        }}
        onClick={event => event.stopPropagation()}
      >
        {text === 'dotsMenu' && (
          <MenuCloseButton type="button" onClick={onClose} aria-label={closeMenuLabel} title={closeMenuLabel}>
            &times;
          </MenuCloseButton>
        )}
        {text === 'compareCards' && (
          <ComparisonCloseButton type="button" onClick={onClose} aria-label="Закрити порівняння">
            &times;
          </ComparisonCloseButton>
        )}
        {body}
      </ContentComponent>
    </ModalOverlay>
  );
};

export default InfoModal;
